import json
import logging

import azure.functions as func
from azure_functions_logging import with_context

from app.services.webhook_service import get_webhook_secret, verify_signature, webhook_store

webhooks_blueprint = func.Blueprint()  # type: ignore[no-untyped-call]


# ---------------------------------------------------------------------------
# POST /api/webhooks/inbound — receive inbound webhook events
# ---------------------------------------------------------------------------

@webhooks_blueprint.route(
    route="webhooks/inbound",
    methods=["POST"],
    auth_level=func.AuthLevel.FUNCTION,
)
@with_context(strict=True)
def receive_webhook(
    req: func.HttpRequest,
    context: func.Context,
) -> func.HttpResponse:
    # --- Signature verification (must run before body parsing) ---
    try:
        secret = get_webhook_secret()
    except RuntimeError:
        return func.HttpResponse(
            body=json.dumps({"error": "Webhook signing secret not configured"}),
            mimetype="application/json",
            status_code=503,
        )

    signature = req.headers.get("X-Signature", "")
    payload = req.get_body()
    if len(payload) > 1024 * 1024:
        return func.HttpResponse(
            body=json.dumps({"error": "Request body too large"}),
            mimetype="application/json",
            status_code=413,
        )
    if not verify_signature(payload, signature, secret):
        logging.warning("Webhook signature verification failed")
        return func.HttpResponse(
            body=json.dumps({"error": "Invalid signature"}),
            mimetype="application/json",
            status_code=401,
        )
    try:
        body = req.get_json()
    except ValueError:
        return func.HttpResponse(
            body=json.dumps({"error": "Invalid JSON body"}),
            mimetype="application/json",
            status_code=400,
        )
    if not isinstance(body, dict):
        return func.HttpResponse(
            body=json.dumps({"error": "Request body must be a JSON object"}),
            mimetype="application/json",
            status_code=400,
        )

    event_type = body.get("event_type", "")
    source = body.get("source", "")
    if not event_type or not source:
        return func.HttpResponse(
            body=json.dumps({"error": "event_type and source are required"}),
            mimetype="application/json",
            status_code=400,
        )

    logging.info("Webhook verified: body_bytes=%d", len(payload))

    entry = webhook_store.record(event_type, source)
    return func.HttpResponse(
        body=json.dumps(entry),
        mimetype="application/json",
        status_code=202,
    )

